<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {useI18n} from 'vue-i18n'
import {api,errorMessage} from '../lib/api'
import {SnapshotGate} from '../lib/requests'
import {formatValue,unit} from '../lib/state'
import {statistics,historyRooms} from '../lib/history'
import type {History,Metric,ChartMetric,Room,Sensor} from '../lib/types'
import HistoryChart from '../components/HistoryChart.vue'
import Notice from '../components/Notice.vue'
import Icon from '../components/Icon.vue'
const {t}=useI18n(),route=useRoute()
const history=ref<History|null>(null),rooms=ref<Room[]>([]),sensors=ref<Sensor[]>([]),selected=ref<string[]>([]),loading=ref(true),error=ref(''),metric=ref<ChartMetric>('temperature'),preset=ref('last24'),bucket=ref('hour')
const requestGate=new SnapshotGate(),resultBucket=ref('hour')
const end=ref(Date.now()),start=ref(end.value-86400000)
function localInput(n:number){const d=new Date(n);return new Date(n-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
const from=ref(localInput(start.value)),to=ref(localInput(end.value))
const allRooms=computed(()=>{const list=[...rooms.value];for(const p of history.value?.points??[])if(p.room_id&&!list.some(r=>r.id===p.room_id))list.push({id:p.room_id,name:p.room_id,temperature:null,humidity:null,available:false});return list})
const visibleRooms=computed(()=>historyRooms(rooms.value,sensors.value,history.value?.points??[]))
const visibleSelected=computed(()=>{const ids=new Set(visibleRooms.value.map(room=>room.id));return selected.value.filter(id=>ids.has(id))})
const table=computed(()=>visibleSelected.value.flatMap(id=>(metric.value==='both'?['temperature','humidity'] as Metric[]:[metric.value]).map(kind=>({id,metric:kind,name:allRooms.value.find(r=>r.id===id)?.name??id,stats:statistics(history.value?.points??[],id,kind)}))))
const roomIntervals=computed(()=>Object.fromEntries(allRooms.value.map(room=>{const ids=new Set(history.value?.points.filter(p=>p.room_id===room.id).map(p=>p.sensor_id)??[]);const intervals=sensors.value.filter(s=>ids.has(s.id)||s.room_id===room.id).map(s=>s.sample_interval_seconds);return [room.id,intervals.length?Math.min(...intervals):900]})))
async function load(){error.value='';loading.value=true;try{if(preset.value==='custom'){start.value=Date.parse(from.value);end.value=Date.parse(to.value)}else{end.value=Date.now();start.value=end.value-({last24:1,last7:7,last30:30}[preset.value as 'last24'|'last7'|'last30']??1)*86400000;from.value=localInput(start.value);to.value=localInput(end.value)}if(!Number.isFinite(start.value)||!Number.isFinite(end.value)||start.value>=end.value||end.value-start.value>366*86400000)throw new Error(t('rangeInvalid'));const params=new URLSearchParams({start:new Date(start.value).toISOString(),end:new Date(end.value).toISOString(),bucket:bucket.value});const ticket=requestGate.begin(params.toString()),requestedBucket=bucket.value;const result=await api<History>('/history?'+params);if(requestGate.isLatest(ticket)){history.value=result;resultBucket.value=requestedBucket}}catch(e){history.value=null;error.value=errorMessage(e)}finally{loading.value=false}}
async function initialize(){try{[rooms.value,sensors.value]=await Promise.all([api<Room[]>('/rooms'),api<Sensor[]>('/sensors')]);await load();const requested=route.query.room?String(route.query.room):'';selected.value=requested&&visibleRooms.value.some(r=>r.id===requested)?[requested]:allRooms.value.map(r=>r.id)}catch(e){error.value=errorMessage(e);loading.value=false}}
function setPreset(key:string){if(loading.value)return;preset.value=key;if(key!=='custom'){bucket.value=key==='last24'?'hour':'day';void load()}}
watch(bucket,()=>{if(!loading.value)void load()})
onMounted(()=>void initialize())
</script>
<template>
<main class="page">
<header class="page-header"><div><div class="eyebrow">SENSOGRID / {{ t('history') }}</div><h1>{{ t('history') }}</h1><p>{{ t('missingData') }}</p></div><span v-if="history?.source==='demo'" class="tag warn">{{ t('demo') }}</span></header><section class="history-controls"><div class="workspace-heading"><div class="segmented"><button v-for="key in ['last24','last7','last30','custom']" :key="key" :class="{active:preset===key}" :disabled="loading" @click="setPreset(key)">{{ t(key) }}</button></div><div class="segmented"><button :class="{active:metric==='temperature'}" :aria-label="t('temperature')" @click="metric='temperature'"><Icon name="thermo" :size="15" /><span class="desktop-only">{{ t('temperature') }}</span></button><button :class="{active:metric==='humidity'}" :aria-label="t('humidity')" @click="metric='humidity'"><Icon name="drop" :size="15" /><span class="desktop-only">{{ t('humidity') }}</span></button><button :class="{active:metric==='both'}" :aria-label="t('both')" @click="metric='both'"><Icon name="grid" :size="15" /><span class="desktop-only">{{ t('both') }}</span></button></div></div><form class="inline-form" @submit.prevent="load"><template v-if="preset==='custom'"><label>{{ t('from') }}<input v-model="from" type="datetime-local" :disabled="loading" required></label><label>{{ t('to') }}<input v-model="to" type="datetime-local" :disabled="loading" required></label></template><label style="max-width:180px">{{ t('aggregation') }}<select v-model="bucket" :disabled="loading"><option v-for="key in ['raw','hour','day','week','month']" :key="key" :value="key">{{ t(key) }}</option></select></label><button :disabled="loading">{{ t(preset==='custom'?'apply':'refresh') }}</button></form><p v-if="preset==='custom'" class="helper">{{ t('localTime') }}</p><div class="comparison-toggles"><label v-for="room in visibleRooms" :key="room.id" class="check"><input v-model="selected" :disabled="loading" type="checkbox" :value="room.id">{{ room.name }}</label></div></section>
<Notice v-if="error" kind="error">{{ t('error') }}<details><summary>{{ t('details') }}</summary>{{ error }}</details><button class="text-button" @click="initialize">{{ t('retry') }}</button></Notice><div v-if="loading" class="skeleton plan" style="margin-top:25px" :aria-label="t('loading')"></div><div v-else-if="visibleRooms.length&&!visibleSelected.length" class="empty-state"><Icon name="history" :size="32" /><p>{{ t('emptySelection') }}</p></div><template v-else-if="visibleSelected.length&&history?.points.length"><HistoryChart :points="history.points" :rooms="allRooms" :selected="visibleSelected" :metric="metric" :bucket="resultBucket" :intervals="roomIntervals" :start="start" :end="end" /><table class="stats-table"><thead><tr><th>{{ t('room') }}</th><th>{{ t('minimum') }}</th><th>{{ t('average') }}</th><th>{{ t('maximum') }}</th><th class="desktop-only">{{ t('pointCount') }}</th></tr></thead><tbody><tr v-for="row in table" :key="row.id+row.metric"><td>{{ row.name }}<small v-if="metric==='both'" class="metric-name">{{ t(row.metric) }}</small></td><td>{{ formatValue(row.stats?.min,row.metric) }} {{ unit(row.metric) }}</td><td>{{ formatValue(row.stats?.average,row.metric) }} {{ unit(row.metric) }}</td><td>{{ formatValue(row.stats?.max,row.metric) }} {{ unit(row.metric) }}</td><td class="desktop-only">{{ row.stats?.count??0 }}</td></tr></tbody></table></template><div v-else-if="!error" class="empty-state"><Icon name="history" :size="32" /><h2>{{ t('noHistory') }}</h2></div>
</main>
</template>
